#!/usr/bin/env python3
"""Dump objects from each PDF to understand structure."""
import re
import zlib

def parse_objects(data):
    objs = {}
    for m in re.finditer(rb"(\d+) 0 obj", data):
        num = int(m.group(1))
        start = m.start()
        # find the endobj that terminates this object: the next 'endobj' occurrence
        end_rel = data.find(b"endobj", m.end())
        if end_rel == -1:
            continue
        end = end_rel + len(b"endobj")
        objs[num] = data[start:end]
    return objs

for name in ["report_part1.pdf", "report_part2.pdf"]:
    print(f"===== {name} =====")
    data = open(name, "rb").read()
    objs = parse_objects(data)
    for num in sorted(objs):
        body = objs[num]
        print(f"--- object {num} ({len(body)} bytes) ---")
        print(body[:1200])
        print()
    print()

import importlib

for mod in ["pypdf", "pypdfium2", "pdfplumber", "reportlab", "PyPDF2", "fitz"]:
    try:
        importlib.import_module(mod)
        print(mod, "OK")
    except ImportError:
        print(mod, "MISSING")

import os
import shutil
import subprocess

INPUTS = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT = "combined_report.pdf"


def merge_pypdf():
    try:
        from pypdf import PdfReader, PdfWriter
    except ImportError:
        return False
    writer = PdfWriter()
    for name in INPUTS:
        for page in PdfReader(name).pages:
            writer.add_page(page)
    with open(OUTPUT, "wb") as f:
        writer.write(f)
    return True


def merge_pypdf2():
    try:
        from PyPDF2 import PdfReader, PdfWriter
    except ImportError:
        return False
    writer = PdfWriter()
    for name in INPUTS:
        for page in PdfReader(name).pages:
            writer.add_page(page)
    with open(OUTPUT, "wb") as f:
        writer.write(f)
    return True


def merge_pypdfium2():
    try:
        import pypdfium2 as pdfium
    except ImportError:
        return False
    out = pdfium.PdfDocument.new()
    for name in INPUTS:
        src = pdfium.PdfDocument(name)
        out.import_pages(src)
        src.close()
    out.save(OUTPUT)
    out.close()
    return True


def merge_qpdf():
    if not shutil.which("qpdf"):
        return False
    subprocess.run(
        ["qpdf", "--empty", "--pages"] + INPUTS + ["--", OUTPUT],
        check=True,
    )
    return True


def merge_pdfunite():
    if not shutil.which("pdfunite"):
        return False
    subprocess.run(["pdfunite"] + INPUTS + [OUTPUT], check=True)
    return True


def merge_pdftk():
    if not shutil.which("pdftk"):
        return False
    subprocess.run(["pdftk"] + INPUTS + ["cat", "output", OUTPUT], check=True)
    return True


def merge_gs():
    if not shutil.which("gs"):
        return False
    subprocess.run(
        ["gs", "-q", "-dNOPAUSE", "-dBATCH", "-sDEVICE=pdfwrite",
         "-sOutputFile=" + OUTPUT] + INPUTS,
        check=True,
    )
    return True


def main():
    for name in INPUTS:
        if not os.path.exists(name):
            raise SystemExit(f"Missing input file: {name}")
    strategies = [
        merge_pypdf,
        merge_pypdf2,
        merge_pypdfium2,
        merge_qpdf,
        merge_pdfunite,
        merge_pdftk,
        merge_gs,
    ]
    for strategy in strategies:
        try:
            if strategy():
                print(f"Merged {', '.join(INPUTS)} -> {OUTPUT} via {strategy.__name__}")
                return
        except Exception as exc:
            print(f"{strategy.__name__} failed: {exc}")
    raise SystemExit("No usable PDF merge mechanism found")


if __name__ == "__main__":
    main()

import importlib.util
import os
import shutil
import subprocess
import sys

INPUTS = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT = "combined_report.pdf"

for name in INPUTS:
    if not os.path.exists(name):
        raise SystemExit(f"Missing input file: {name}")

available_modules = []
for mod in ["pypdf", "PyPDF2", "pypdfium2", "fitz", "pikepdf", "pdfrw",
            "pdfplumber", "img2pdf", "fpdf", "reportlab", "borb"]:
    if importlib.util.find_spec(mod):
        available_modules.append(mod)

available_bins = []
for binname in ["qpdf", "pdfunite", "pdftk", "gs", "mutool", "cpdf",
                "pdfjam", "stapler", "convert", "magick", "img2pdf"]:
    if shutil.which(binname):
        available_bins.append(binname)

print("python:", sys.executable)
print("available_modules:", available_modules)
print("available_bins:", available_bins)

errors = []


def run_merge(desc, fn):
    try:
        fn()
        if os.path.exists(OUTPUT) and os.path.getsize(OUTPUT) > 0:
            print(f"MERGED via {desc}")
            return True
    except Exception as exc:
        errors.append(f"{desc}: {exc}")
    return False


def m_pypdf():
    from pypdf import PdfReader, PdfWriter
    w = PdfWriter()
    for n in INPUTS:
        for p in PdfReader(n).pages:
            w.add_page(p)
    with open(OUTPUT, "wb") as f:
        w.write(f)


def m_pypdf2():
    from PyPDF2 import PdfReader, PdfWriter
    w = PdfWriter()
    for n in INPUTS:
        for p in PdfReader(n).pages:
            w.add_page(p)
    with open(OUTPUT, "wb") as f:
        w.write(f)


def m_pypdfium2():
    import pypdfium2 as pdfium
    out = pdfium.PdfDocument.new()
    for n in INPUTS:
        src = pdfium.PdfDocument(n)
        out.import_pages(src)
        src.close()
    out.save(OUTPUT)
    out.close()


def m_fitz():
    import fitz
    out = fitz.open()
    for n in INPUTS:
        src = fitz.open(n)
        out.insert_pdf(src)
        src.close()
    out.save(OUTPUT)
    out.close()


def m_pikepdf():
    import pikepdf
    out = pikepdf.new()
    for n in INPUTS:
        with pikepdf.open(n) as src:
            out.pages.extend(src.pages)
    out.save(OUTPUT)


def m_pdfrw():
    from pdfrw import PdfReader, PdfWriter
    out = PdfWriter()
    for n in INPUTS:
        out.addpages(PdfReader(n).pages)
    out.write(OUTPUT)


def m_img2pdf():
    import img2pdf
    data = b""
    for n in INPUTS:
        with open(n, "rb") as f:
            data += f.read()
    with open(OUTPUT, "wb") as f:
        f.write(img2pdf.convert(img2pdf.pdfdoc.PdfFile(data).pages))


def m_qpdf():
    subprocess.run(["qpdf", "--empty", "--pages"] + INPUTS + ["--", OUTPUT], check=True)


def m_pdfunite():
    subprocess.run(["pdfunite"] + INPUTS + [OUTPUT], check=True)


def m_pdftk():
    subprocess.run(["pdftk"] + INPUTS + ["cat", "output", OUTPUT], check=True)


def m_gs():
    subprocess.run(["gs", "-q", "-dNOPAUSE", "-dBATCH", "-sDEVICE=pdfwrite",
                    "-sOutputFile=" + OUTPUT] + INPUTS, check=True)


def m_mutool():
    subprocess.run(["mutool", "merge", "-o", OUTPUT] + INPUTS, check=True)


def m_cpdf():
    subprocess.run(["cpdf", "-merge"] + INPUTS + ["-o", OUTPUT], check=True)


def m_pdfjam():
    subprocess.run(["pdfjam"] + INPUTS + ["--outfile", OUTPUT], check=True)


def m_stapler():
    subprocess.run(["stapler", "cat"] + INPUTS + ["-o", OUTPUT], check=True)


def m_convert():
    subprocess.run(["convert", "-density", "150"] + INPUTS + [OUTPUT], check=True)


strategies = [
    ("pypdf", m_pypdf),
    ("PyPDF2", m_pypdf2),
    ("pypdfium2", m_pypdfium2),
    ("fitz/PyMuPDF", m_fitz),
    ("pikepdf", m_pikepdf),
    ("pdfrw", m_pdfrw),
    ("img2pdf", m_img2pdf),
    ("qpdf", m_qpdf),
    ("pdfunite", m_pdfunite),
    ("pdftk", m_pdftk),
    ("ghostscript", m_gs),
    ("mutool", m_mutool),
    ("cpdf", m_cpdf),
    ("pdfjam", m_pdfjam),
    ("stapler", m_stapler),
    ("imagemagick convert", m_convert),
]

for desc, fn in strategies:
    if run_merge(desc, fn):
        sys.exit(0)

print("All strategies failed. Errors:")
for e in errors:
    print(" -", e)
sys.exit(1)

"""Merge report_part1.pdf and report_part2.pdf into combined_report.pdf.

Strategy 1: use any available PDF library found on sys.path candidates.
Strategy 2: use any available PDF CLI tool.
Strategy 3: pure-Python merge using only the standard library.
"""
import importlib
import os
import re
import shutil
import subprocess
import sys
import zlib

INPUTS = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT = "combined_report.pdf"

for name in INPUTS:
    if not os.path.exists(name):
        sys.exit(f"Missing input file: {name}")

WHITESPACE = b"\x00\t\n\x0c\r "
DELIMS = b"()<>[]{}/%"


# --------------------------------------------------------------------------
# Strategy 1: library discovery via sys.path candidates
# --------------------------------------------------------------------------
def find_site_packages():
    found = []
    roots = [
        os.getcwd(),
        os.path.abspath(os.path.join(os.getcwd(), "..")),
        os.path.abspath(os.path.join(os.getcwd(), "../..")),
        ".codex",
        ".tools",
        "/usr/lib",
        "/usr/local/lib",
    ]
    for root in roots:
        if not root or not os.path.isdir(root):
            continue
        for dirpath, dirnames, filenames in os.walk(root):
            depth = dirpath[len(root):].count(os.sep)
            if depth > 5:
                dirnames[:] = []
                continue
            base = os.path.basename(dirpath)
            if base in ("site-packages", "dist-packages"):
                found.append(dirpath)
                dirnames[:] = []
    return found


def merge_with_library():
    for sp in find_site_packages():
        if sp not in sys.path:
            sys.path.insert(0, sp)
    modules = ["pypdf", "PyPDF2", "pypdfium2", "fitz", "pikepdf", "pdfrw"]
    available = [m for m in modules if importlib.util.find_spec(m)]
    if "pypdf" in available:
        from pypdf import PdfReader, PdfWriter
        w = PdfWriter()
        for n in INPUTS:
            for p in PdfReader(n).pages:
                w.add_page(p)
        with open(OUTPUT, "wb") as f:
            w.write(f)
        return "pypdf"
    if "PyPDF2" in available:
        from PyPDF2 import PdfReader, PdfWriter
        w = PdfWriter()
        for n in INPUTS:
            for p in PdfReader(n).pages:
                w.add_page(p)
        with open(OUTPUT, "wb") as f:
            w.write(f)
        return "PyPDF2"
    if "pypdfium2" in available:
        import pypdfium2 as pdfium
        out = pdfium.PdfDocument.new()
        for n in INPUTS:
            src = pdfium.PdfDocument(n)
            out.import_pages(src)
            src.close()
        out.save(OUTPUT)
        out.close()
        return "pypdfium2"
    if "fitz" in available:
        import fitz
        out = fitz.open()
        for n in INPUTS:
            src = fitz.open(n)
            out.insert_pdf(src)
            src.close()
        out.save(OUTPUT)
        out.close()
        return "fitz"
    if "pikepdf" in available:
        import pikepdf
        out = pikepdf.new()
        for n in INPUTS:
            with pikepdf.open(n) as src:
                out.pages.extend(src.pages)
        out.save(OUTPUT)
        return "pikepdf"
    if "pdfrw" in available:
        from pdfrw import PdfReader, PdfWriter
        out = PdfWriter()
        for n in INPUTS:
            out.addpages(PdfReader(n).pages)
        out.write(OUTPUT)
        return "pdfrw"
    return None


# --------------------------------------------------------------------------
# Strategy 2: CLI tools
# --------------------------------------------------------------------------
def merge_with_cli():
    clis = [
        (["qpdf", "--empty", "--pages"] + INPUTS + ["--", OUTPUT], "qpdf"),
        (["pdfunite"] + INPUTS + [OUTPUT], "pdfunite"),
        (["pdftk"] + INPUTS + ["cat", "output", OUTPUT], "pdftk"),
        (["gs", "-q", "-dNOPAUSE", "-dBATCH", "-sDEVICE=pdfwrite",
          "-sOutputFile=" + OUTPUT] + INPUTS, "ghostscript"),
        (["mutool", "merge", "-o", OUTPUT] + INPUTS, "mutool"),
        (["cpdf", "-merge"] + INPUTS + ["-o", OUTPUT], "cpdf"),
        (["pdfjam"] + INPUTS + ["--outfile", OUTPUT], "pdfjam"),
        (["stapler", "cat"] + INPUTS + ["-o", OUTPUT], "stapler"),
    ]
    for cmd, name in clis:
        if shutil.which(cmd[0]):
            try:
                subprocess.run(cmd, check=True)
                if os.path.exists(OUTPUT) and os.path.getsize(OUTPUT) > 0:
                    return name
            except Exception:
                continue
    return None


# --------------------------------------------------------------------------
# Strategy 3: pure-Python merge (stdlib only)
# --------------------------------------------------------------------------
class PDFError(Exception):
    pass


class Parser:
    def __init__(self, data, pos=0):
        self.data = data
        self.pos = pos
        self.n = len(data)

    def skip_ws(self):
        d = self.data
        while self.pos < self.n and d[self.pos] in WHITESPACE:
            self.pos += 1

    def read_token(self):
        self.skip_ws()
        d = self.data
        if self.pos >= self.n:
            raise PDFError("unexpected EOF in token")
        c = d[self.pos]
        if c in b"+-.0123456789":
            start = self.pos
            while self.pos < self.n and d[self.pos] in b"+-.0123456789":
                self.pos += 1
            return d[start:self.pos]
        if c == 47:  # /
            start = self.pos
            self.pos += 1
            while self.pos < self.n and d[self.pos] not in WHITESPACE + DELIMS:
                self.pos += 1
            return d[start:self.pos]
        if c == 40:  # (
            start = self.pos
            depth = 1
            self.pos += 1
            while self.pos < self.n:
                ch = d[self.pos]
                if ch == 92:  # backslash escape
                    self.pos += 2
                    continue
                if ch == 40:
                    depth += 1
                elif ch == 41:
                    depth -= 1
                    if depth == 0:
                        self.pos += 1
                        break
                self.pos += 1
            return d[start:self.pos]
        if c == 60:
            if d[self.pos + 1:self.pos + 2] == b"<":
                self.pos += 2
                items = []
                while True:
                    self.skip_ws()
                    if self.data[self.pos:self.pos + 2] == b">>":
                        self.pos += 2
                        break
                    key = self.read_token()
                    if self.data[self.pos:self.pos + 2] == b">>":
                        self.pos += 2
                        break
                    items.append((key, self.parse_value()))
                return ("dict", items)
            start = self.pos
            self.pos += 1
            while self.pos < self.n and d[self.pos] != 62:
                self.pos += 1
            if self.pos < self.n:
                self.pos += 1
            return d[start:self.pos]
        if c == 91:  # [
            self.pos += 1
            arr = []
            while True:
                self.skip_ws()
                if self.pos >= self.n:
                    raise PDFError("EOF inside array")
                if d[self.pos] == 93:
                    self.pos += 1
                    break
                arr.append(self.parse_value())
            return ("array", arr)
        if c == 93:
            self.pos += 1
            return b"]"
        start = self.pos
        while self.pos < self.n and d[self.pos] not in WHITESPACE + DELIMS:
            self.pos += 1
        tok = d[start:self.pos]
        if tok == b"true":
            return True
        if tok == b"false":
            return False
        if tok == b"null":
            return None
        return tok

    def parse_value(self):
        self.skip_ws()
        d = self.data
        if d[self.pos:self.pos + 2] == b"<<":
            return self.read_token()
        c = d[self.pos]
        if c in (40, 60, 91):
            return self.read_token()
        tok = self.read_token()
        if tok is True or tok is False or tok is None:
            return tok
        if isinstance(tok, bytes) and re.fullmatch(rb"[+-]?\d+", tok):
            num = int(tok)
            save = self.pos
            t2 = self.read_token()
            if isinstance(t2, bytes) and re.fullmatch(rb"\d+", t2):
                save2 = self.pos
                t3 = self.read_token()
                if t3 == b"R":
                    return ("ref", num, int(t2))
                self.pos = save2
            self.pos = save
            return num
        return tok

    def parse_object(self, offset):
        self.pos = offset
        self.skip_ws()
        ntok = self.read_token()
        if not isinstance(ntok, bytes) or not re.fullmatch(rb"\d+", ntok):
            raise PDFError(f"bad object header at {offset}")
        num = int(ntok)
        gtok = self.read_token()
        gen = int(gtok) if isinstance(gtok, bytes) else 0
        k = self.read_token()
        if k != b"obj":
            raise PDFError(f"'obj' expected at {offset}")
        value = self.parse_value()
        self.skip_ws()
        if self.data[self.pos:self.pos + 6] == b"stream":
            eol = self.pos + 6
            if self.data[eol:eol + 2] == b"\r\n":
                eol += 2
            elif self.data[eol:eol + 1] in (b"\n", b"\r"):
                eol += 1
            start = eol
            end = self.data.find(b"endstream", start)
            if end < 0:
                raise PDFError(f"no endstream in object {num}")
            stream = self.data[start:end]
            self.pos = end + len(b"endstream")
            self.skip_ws()
            eo = self.data.find(b"endobj", self.pos)
            if eo < 0:
                raise PDFError(f"no endobj after stream in object {num}")
            return num, gen, value, stream, eo + 6
        eo = self.data.find(b"endobj", self.pos)
        if eo < 0:
            raise PDFError(f"no endobj in object {num}")
        return num, gen, value, None, eo + 6


def dict_get(d, key):
    if isinstance(d, tuple) and d[0] == "dict":
        for k, v in d[1]:
            if k == key:
                return v
    return None


def dict_set(d, key, val):
    items = d[1]
    for i, (k, _) in enumerate(items):
        if k == key:
            items[i] = (key, val)
            return
    items.append((key, val))


def parse_classic_xref(data, startxref):
    entries = {}
    trailer = None
    pos = startxref
    while pos is not None:
        if data[pos:pos + 4] != b"xref":
            raise PDFError(f"bad xref at {pos}")
        pos += 4
        while True:
            while pos < len(data) and data[pos] in WHITESPACE:
                pos += 1
            if pos >= len(data):
                break
            if data[pos:pos + 7] == b"trailer":
                p = Parser(data, pos + 7)
                trailer = p.parse_value()
                prev = dict_get(trailer, b"/Prev")
                pos = prev if isinstance(prev, int) else None
                xrefstm = dict_get(trailer, b"/XRefStm")
                if isinstance(xrefstm, int):
                    try:
                        stm_entries, _ = parse_xref_stream(data, xrefstm)
                        entries.update(stm_entries)
                    except Exception:
                        pass
                break
            m = re.match(rb"(\d+)\s+(\d+)", data[pos:])
            if not m:
                raise PDFError("bad xref subsection")
            start = int(m.group(1))
            count = int(m.group(2))
            pos += m.end()
            for _ in range(count):
                ent = data[pos:pos + 20]
                off = int(ent[0:10])
                gen = int(ent[11:16])
                typ = ent[17:18]
                pos += 20
                if typ == b"n":
                    entries[start] = ("off", off, gen)
                elif typ == b"f":
                    entries[start] = ("free", off, gen)
                start += 1
    return entries, trailer


def parse_xref_stream(data, startxref):
    p = Parser(data, startxref)
    num, gen, value, stream, _ = p.parse_object(startxref)
    W = dict_get(value, b"/W")
    if not (isinstance(W, tuple) and W[0] == "array"):
        raise PDFError("xref stream without /W")
    widths = [w for w in W[1] if isinstance(w, int)]
    Index = dict_get(value, b"/Index")
    if isinstance(Index, tuple) and Index[0] == "array":
        pairs = [v for v in Index[1] if isinstance(v, int)]
    else:
        size = dict_get(value, b"/Size")
        pairs = [0, size if isinstance(size, int) else 0]
    try:
        raw = zlib.decompress(stream)
    except Exception:
        raw = stream
    entries = {}
    field_bytes = b"".join(widths)
    pos = 0
    for i in range(0, len(pairs), 2):
        start = pairs[i]
        count = pairs[i + 1]
        for _ in range(count):
            chunk = raw[pos:pos + field_bytes]
            pos += field_bytes
            fields = []
            off = 0
            for w in widths:
                fields.append(int.from_bytes(chunk[off:off + w], "big"))
                off += w
            typ = fields[0] if widths and widths[0] > 0 else 1
            if typ == 1:
                entries[start] = ("off", fields[1], fields[2])
            elif typ == 2:
                entries[start] = ("objstm", fields[1], fields[2])
            else:
                entries[start] = ("free", fields[1], fields[2])
            start += 1
    return entries, value


def parse_objstm(data, objstm_num, index):
    p = Parser(data, objstm_num)
    num, gen, value, stream, _ = p.parse_object(objstm_num)
    raw = zlib.decompress(stream) if stream else b""
    sp = Parser(raw, 0)
    header = []
    for _ in range(2):
        tok = sp.read_token()
        header.append(int(tok) if isinstance(tok, bytes) else 0)
    n_objs = header[0]
    first = header[1]
    pairs = []
    for _ in range(n_objs):
        o = int(sp.read_token())
        off = int(sp.read_token())
        pairs.append((o, off))
    for o, off in pairs:
        if o == index:
            op = Parser(raw, off)
            return op.parse_value()
    raise PDFError(f"object {index} not found in ObjStm {objstm_num}")


def load_doc(path):
    with open(path, "rb") as f:
        data = f.read()
    m = re.search(rb"startxref\s+(\d+)", data)
    if not m:
        raise PDFError(f"no startxref in {path}")
    startxref = int(m.group(1))
    if data[startxref:startxref + 4] == b"xref":
        entries, trailer = parse_classic_xref(data, startxref)
    else:
        entries, trailer = parse_xref_stream(data, startxref)
        # follow /Prev chain of xref streams
        prev = dict_get(trailer, b"/Prev")
        while isinstance(prev, int):
            more, _ = parse_xref_stream(data, prev)
            entries.update(more)
            prev = dict_get(_, b"/Prev")
    root = dict_get(trailer, b"/Root")
    if not (isinstance(root, tuple) and root[0] == "ref"):
        raise PDFError(f"no /Root in trailer of {path}")
    if dict_get(trailer, b"/Encrypt") is not None:
        raise PDFError(f"encrypted PDF not supported: {path}")
    # parse every object referenced by the xref
    objects = {}
    for num, (kind, a, b) in entries.items():
        if kind == "off":
            try:
                objects[num] = Parser(data, a).parse_object(a)
            except Exception:
                continue
        elif kind == "objstm":
            try:
                val = parse_objstm(data, a, b)
                objects[num] = (num, 0, val, None, 0)
            except Exception:
                continue
    return data, entries, trailer, root[1], objects


def serialize_value(v, renum):
    if v is True:
        return b"true"
    if v is False:
        return b"false"
    if v is None:
        return b"null"
    if isinstance(v, int):
        return str(v).encode()
    if isinstance(v, bytes):
        return v
    if isinstance(v, tuple):
        if v[0] == "ref":
            n, g = v[1], v[2]
            return b"%d %d R" % (renum.get(n, n), g)
        if v[0] == "array":
            return b"[" + b" ".join(serialize_value(x, renum) for x in v[1]) + b"]"
        if v[0] == "dict":
            parts = []
            for k, val in v[1]:
                parts.append(k + b" " + serialize_value(val, renum))
            return b"<<" + b" ".join(parts) + b">>"
    raise PDFError(f"cannot serialize {v!r}")


def serialize_object(objnum, gen, value, stream, renum):
    head = b"%d %d obj\n" % (objnum, gen)
    body = serialize_value(value, renum)
    if stream is not None:
        return head + body + b"\nstream\n" + stream + b"\nendstream\nendobj\n"
    return head + body + b"\nendobj\n"


def pure_python_merge():
    doc1 = load_doc(INPUTS[0])
    doc2 = load_doc(INPUTS[1])
    objs1 = doc1[4]
    objs2 = doc2[4]
    if not objs1 or not objs2:
        raise PDFError("no parseable objects")
    max1 = max(objs1)
    max2 = max(objs2)
    offset2 = max1 + 1
    newroot_num = offset2 + max2

    cat1_num = doc1[3]
    cat2_num = doc2[3]
    cat1 = objs1.get(cat1_num)
    cat2 = objs2.get(cat2_num)
    if cat1 is None:
        raise PDFError("catalog 1 missing")
    pages1_ref = dict_get(cat1[2], b"/Pages")
    pages2_ref = dict_get(cat2[2], b"/Pages")
    if not (isinstance(pages1_ref, tuple) and pages1_ref[0] == "ref"):
        raise PDFError("no /Pages in catalog 1")
    if not (isinstance(pages2_ref, tuple) and pages2_ref[0] == "ref"):
        raise PDFError("no /Pages in catalog 2")
    pages1_num = pages1_ref[1]
    pages2_num = pages2_ref[1] + offset2

    count1 = 0
    count2 = 0

    def count_pages(pages_value):
        c = dict_get(pages_value, b"/Count")
        return c if isinstance(c, int) else 0

    p1 = objs1.get(pages1_ref[1])
    p2 = objs2.get(pages2_ref[1])
    if p1 is not None:
        count1 = count_pages(p1[2])
    if p2 is not None:
        count2 = count_pages(p2[2])

    # new root Pages object
    newroot_value = ("dict", [
        (b"/Type", b"/Pages"),
        (b"/Kids", ("array", [
            ("ref", pages1_ref[1], 0),
            ("ref", pages2_num, 0),
        ])),
        (b"/Count", count1 + count2),
    ])

    # patch page roots with /Parent -> new root
    if p1 is not None:
        dict_set(p1[2], b"/Parent", ("ref", newroot_num, 0))
    if p2 is not None:
        dict_set(p2[2], b"/Parent", ("ref", newroot_num, 0))

    # patch catalog 1: /Pages -> new root
    dict_set(cat1[2], b"/Pages", ("ref", newroot_num, 0))

    renum = {n: n for n in objs1}
    renum.update({n: n + offset2 for n in objs2})

    out = bytearray()
    xref = []  # (offset, gen)
    max_out = newroot_num

    def emit(num, gen, value, stream):
        nonlocal out
        off = len(out)
        out += serialize_object(num, gen, value, stream, renum)
        while len(xref) < num + 1:
            xref.append(None)
        xref[num] = (off, gen)

    for n in sorted(objs1):
        o = objs1[n]
        emit(n, o[1], o[2], o[3])
    for n in sorted(objs2):
        o = objs2[n]
        emit(n + offset2, o[1], o[2], o[3])
    emit(newroot_num, 0, newroot_value, None)

    header = b"%PDF-1.4\n"
    body = bytes(out)
    xref_offset = len(header) + len(body)
    size = max_out + 1
    lines = [b"xref\n", b"0 %d\n" % size, b"0000000000 65535 f \n"]
    for i in range(1, size):
        e = xref[i] if i < len(xref) else None
        if e is None:
            lines.append(b"0000000000 00000 f \n")
        else:
            lines.append(b"%010d %05d n \n" % (e[0], e[1]))
    trailer = b"trailer\n<< /Size %d /Root %d 0 R >>\n" % (size, cat1_num)
    tail = (b"".join(lines) + trailer + b"startxref\n%d\n%%%%EOF\n" % xref_offset)
    with open(OUTPUT, "wb") as f:
        f.write(header + body + tail)
    return f"pure-python (pages 1={count1}, 2={count2})"


def main():
    lib = merge_with_library()
    if lib:
        print("MERGED via", lib)
        return
    cli = merge_with_cli()
    if cli:
        print("MERGED via", cli)
        return
    method = pure_python_merge()
    if os.path.exists(OUTPUT) and os.path.getsize(OUTPUT) > 0:
        print("MERGED via", method)
        print("Output:", OUTPUT, os.path.getsize(OUTPUT), "bytes")
    else:
        sys.exit("merge produced no output")


if __name__ == "__main__":
    main()

"""Merge report_part1.pdf and report_part2.pdf into combined_report.pdf.

Strategy 1: use any available PDF library found on sys.path candidates.
Strategy 2: use any available PDF CLI tool.
Strategy 3: pure-Python merge using only the standard library.
"""
import importlib
import importlib.util
import os
import re
import shutil
import subprocess
import sys
import zlib

INPUTS = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT = "combined_report.pdf"

for name in INPUTS:
    if not os.path.exists(name):
        sys.exit(f"Missing input file: {name}")

WHITESPACE = b"\x00\t\n\x0c\r "
DELIMS = b"()<>[]{}/%"


# --------------------------------------------------------------------------
# Strategy 1: library discovery via sys.path candidates
# --------------------------------------------------------------------------
def find_site_packages():
    found = []
    roots = [
        os.getcwd(),
        os.path.abspath(os.path.join(os.getcwd(), "..")),
        os.path.abspath(os.path.join(os.getcwd(), "../..")),
        ".codex",
        ".tools",
        "/usr/lib",
        "/usr/local/lib",
    ]
    for root in roots:
        if not root or not os.path.isdir(root):
            continue
        for dirpath, dirnames, filenames in os.walk(root):
            depth = dirpath[len(root):].count(os.sep)
            if depth > 5:
                dirnames[:] = []
                continue
            base = os.path.basename(dirpath)
            if base in ("site-packages", "dist-packages"):
                found.append(dirpath)
                dirnames[:] = []
    return found


def merge_with_library():
    for sp in find_site_packages():
        if sp not in sys.path:
            sys.path.insert(0, sp)
    modules = ["pypdf", "PyPDF2", "pypdfium2", "fitz", "pikepdf", "pdfrw"]
    available = [m for m in modules if importlib.util.find_spec(m)]
    if "pypdf" in available:
        from pypdf import PdfReader, PdfWriter
        w = PdfWriter()
        for n in INPUTS:
            for p in PdfReader(n).pages:
                w.add_page(p)
        with open(OUTPUT, "wb") as f:
            f.write(w.write() if hasattr(w, "write") and False else b"")
        # pypdf PdfWriter.write takes a stream; write properly below
        with open(OUTPUT, "wb") as f:
            w.write(f)
        return "pypdf"
    if "PyPDF2" in available:
        from PyPDF2 import PdfReader, PdfWriter
        w = PdfWriter()
        for n in INPUTS:
            for p in PdfReader(n).pages:
                w.add_page(p)
        with open(OUTPUT, "wb") as f:
            w.write(f)
        return "PyPDF2"
    if "pypdfium2" in available:
        import pypdfium2 as pdfium
        out = pdfium.PdfDocument.new()
        for n in INPUTS:
            src = pdfium.PdfDocument(n)
            out.import_pages(src)
            src.close()
        out.save(OUTPUT)
        out.close()
        return "pypdfium2"
    if "fitz" in available:
        import fitz
        out = fitz.open()
        for n in INPUTS:
            src = fitz.open(n)
            out.insert_pdf(src)
            src.close()
        out.save(OUTPUT)
        out.close()
        return "fitz"
    if "pikepdf" in available:
        import pikepdf
        out = pikepdf.new()
        for n in INPUTS:
            with pikepdf.open(n) as src:
                out.pages.extend(src.pages)
        out.save(OUTPUT)
        return "pikepdf"
    if "pdfrw" in available:
        from pdfrw import PdfReader, PdfWriter
        out = PdfWriter()
        for n in INPUTS:
            out.addpages(PdfReader(n).pages)
        out.write(OUTPUT)
        return "pdfrw"
    return None


# --------------------------------------------------------------------------
# Strategy 2: CLI tools
# --------------------------------------------------------------------------
def merge_with_cli():
    clis = [
        (["qpdf", "--empty", "--pages"] + INPUTS + ["--", OUTPUT], "qpdf"),
        (["pdfunite"] + INPUTS + [OUTPUT], "pdfunite"),
        (["pdftk"] + INPUTS + ["cat", "output", OUTPUT], "pdftk"),
        (["gs", "-q", "-dNOPAUSE", "-dBATCH", "-sDEVICE=pdfwrite",
          "-sOutputFile=" + OUTPUT] + INPUTS, "ghostscript"),
        (["mutool", "merge", "-o", OUTPUT] + INPUTS, "mutool"),
        (["cpdf", "-merge"] + INPUTS + ["-o", OUTPUT], "cpdf"),
        (["pdfjam"] + INPUTS + ["--outfile", OUTPUT], "pdfjam"),
        (["stapler", "cat"] + INPUTS + ["-o", OUTPUT], "stapler"),
    ]
    for cmd, name in clis:
        if shutil.which(cmd[0]):
            try:
                subprocess.run(cmd, check=True)
                if os.path.exists(OUTPUT) and os.path.getsize(OUTPUT) > 0:
                    return name
            except Exception:
                continue
    return None


# --------------------------------------------------------------------------
# Strategy 3: pure-Python merge (stdlib only)
# --------------------------------------------------------------------------
class PDFError(Exception):
    pass


class Parser:
    def __init__(self, data, pos=0):
        self.data = data
        self.pos = pos
        self.n = len(data)

    def skip_ws(self):
        d = self.data
        while self.pos < self.n and d[self.pos] in WHITESPACE:
            self.pos += 1

    def read_token(self):
        self.skip_ws()
        d = self.data
        if self.pos >= self.n:
            raise PDFError("unexpected EOF in token")
        c = d[self.pos]
        if c in b"+-.0123456789":
            start = self.pos
            while self.pos < self.n and d[self.pos] in b"+-.0123456789":
                self.pos += 1
            return d[start:self.pos]
        if c == 47:  # /
            start = self.pos
            self.pos += 1
            while self.pos < self.n and d[self.pos] not in WHITESPACE + DELIMS:
                self.pos += 1
            return d[start:self.pos]
        if c == 40:  # (
            start = self.pos
            depth = 1
            self.pos += 1
            while self.pos < self.n:
                ch = d[self.pos]
                if ch == 92:  # backslash escape
                    self.pos += 2
                    continue
                if ch == 40:
                    depth += 1
                elif ch == 41:
                    depth -= 1
                    if depth == 0:
                        self.pos += 1
                        break
                self.pos += 1
            return d[start:self.pos]
        if c == 60:
            if d[self.pos + 1:self.pos + 2] == b"<":
                self.pos += 2
                items = []
                while True:
                    self.skip_ws()
                    if self.data[self.pos:self.pos + 2] == b">>":
                        self.pos += 2
                        break
                    key = self.read_token()
                    if self.data[self.pos:self.pos + 2] == b">>":
                        self.pos += 2
                        break
                    items.append((key, self.parse_value()))
                return ("dict", items)
            start = self.pos
            self.pos += 1
            while self.pos < self.n and d[self.pos] != 62:
                self.pos += 1
            if self.pos < self.n:
                self.pos += 1
            return d[start:self.pos]
        if c == 91:  # [
            self.pos += 1
            arr = []
            while True:
                self.skip_ws()
                if self.pos >= self.n:
                    raise PDFError("EOF inside array")
                if d[self.pos] == 93:
                    self.pos += 1
                    break
                arr.append(self.parse_value())
            return ("array", arr)
        if c == 93:
            self.pos += 1
            return b"]"
        start = self.pos
        while self.pos < self.n and d[self.pos] not in WHITESPACE + DELIMS:
            self.pos += 1
        tok = d[start:self.pos]
        if tok == b"true":
            return True
        if tok == b"false":
            return False
        if tok == b"null":
            return None
        return tok

    def parse_value(self):
        self.skip_ws()
        d = self.data
        if d[self.pos:self.pos + 2] == b"<<":
            return self.read_token()
        c = d[self.pos]
        if c in (40, 60, 91):
            return self.read_token()
        tok = self.read_token()
        if tok is True or tok is False or tok is None:
            return tok
        if isinstance(tok, bytes) and re.fullmatch(rb"[+-]?\d+", tok):
            num = int(tok)
            save = self.pos
            t2 = self.read_token()
            if isinstance(t2, bytes) and re.fullmatch(rb"\d+", t2):
                save2 = self.pos
                t3 = self.read_token()
                if t3 == b"R":
                    return ("ref", num, int(t2))
                self.pos = save2
            self.pos = save
            return num
        return tok

    def parse_object(self, offset):
        self.pos = offset
        self.skip_ws()
        ntok = self.read_token()
        if not isinstance(ntok, bytes) or not re.fullmatch(rb"\d+", ntok):
            raise PDFError(f"bad object header at {offset}")
        num = int(ntok)
        gtok = self.read_token()
        gen = int(gtok) if isinstance(gtok, bytes) else 0
        k = self.read_token()
        if k != b"obj":
            raise PDFError(f"'obj' expected at {offset}")
        value = self.parse_value()
        self.skip_ws()
        if self.data[self.pos:self.pos + 6] == b"stream":
            eol = self.pos + 6
            if self.data[eol:eol + 2] == b"\r\n":
                eol += 2
            elif self.data[eol:eol + 1] in (b"\n", b"\r"):
                eol += 1
            start = eol
            end = self.data.find(b"endstream", start)
            if end < 0:
                raise PDFError(f"no endstream in object {num}")
            stream = self.data[start:end]
            self.pos = end + len(b"endstream")
            self.skip_ws()
            eo = self.data.find(b"endobj", self.pos)
            if eo < 0:
                raise PDFError(f"no endobj after stream in object {num}")
            return num, gen, value, stream, eo + 6
        eo = self.data.find(b"endobj", self.pos)
        if eo < 0:
            raise PDFError(f"no endobj in object {num}")
        return num, gen, value, None, eo + 6


def dict_get(d, key):
    if isinstance(d, tuple) and d[0] == "dict":
        for k, v in d[1]:
            if k == key:
                return v
    return None


def dict_set(d, key, val):
    items = d[1]
    for i, (k, _) in enumerate(items):
        if k == key:
            items[i] = (key, val)
            return
    items.append((key, val))


def parse_classic_xref(data, startxref):
    entries = {}
    trailer = None
    pos = startxref
    while pos is not None:
        if data[pos:pos + 4] != b"xref":
            raise PDFError(f"bad xref at {pos}")
        pos += 4
        while True:
            while pos < len(data) and data[pos] in WHITESPACE:
                pos += 1
            if pos >= len(data):
                break
            if data[pos:pos + 7] == b"trailer":
                p = Parser(data, pos + 7)
                trailer = p.parse_value()
                prev = dict_get(trailer, b"/Prev")
                pos = prev if isinstance(prev, int) else None
                xrefstm = dict_get(trailer, b"/XRefStm")
                if isinstance(xrefstm, int):
                    try:
                        stm_entries, _ = parse_xref_stream(data, xrefstm)
                        entries.update(stm_entries)
                    except Exception:
                        pass
                break
            m = re.match(rb"(\d+)\s+(\d+)", data[pos:])
            if not m:
                raise PDFError("bad xref subsection")
            start = int(m.group(1))
            count = int(m.group(2))
            pos += m.end()
            for _ in range(count):
                ent = data[pos:pos + 20]
                off = int(ent[0:10])
                gen = int(ent[11:16])
                typ = ent[17:18]
                pos += 20
                if typ == b"n":
                    entries[start] = ("off", off, gen)
                elif typ == b"f":
                    entries[start] = ("free", off, gen)
                start += 1
    return entries, trailer


def parse_xref_stream(data, startxref):
    p = Parser(data, startxref)
    num, gen, value, stream, _ = p.parse_object(startxref)
    W = dict_get(value, b"/W")
    if not (isinstance(W, tuple) and W[0] == "array"):
        raise PDFError("xref stream without /W")
    widths = [w for w in W[1] if isinstance(w, int)]
    Index = dict_get(value, b"/Index")
    if isinstance(Index, tuple) and Index[0] == "array":
        pairs = [v for v in Index[1] if isinstance(v, int)]
    else:
        size = dict_get(value, b"/Size")
        pairs = [0, size if isinstance(size, int) else 0]
    try:
        raw = zlib.decompress(stream)
    except Exception:
        raw = stream
    entries = {}
    field_bytes = b"".join(widths)
    pos = 0
    for i in range(0, len(pairs), 2):
        start = pairs[i]
        count = pairs[i + 1]
        for _ in range(count):
            chunk = raw[pos:pos + field_bytes]
            pos += field_bytes
            fields = []
            off = 0
            for w in widths:
                fields.append(int.from_bytes(chunk[off:off + w], "big"))
                off += w
            typ = fields[0] if widths and widths[0] > 0 else 1
            if typ == 1:
                entries[start] = ("off", fields[1], fields[2])
            elif typ == 2:
                entries[start] = ("objstm", fields[1], fields[2])
            else:
                entries[start] = ("free", fields[1], fields[2])
            start += 1
    return entries, value


def parse_objstm(data, objstm_num, index):
    p = Parser(data, objstm_num)
    num, gen, value, stream, _ = p.parse_object(objstm_num)
    raw = zlib.decompress(stream) if stream else b""
    sp = Parser(raw, 0)
    header = []
    for _ in range(2):
        tok = sp.read_token()
        header.append(int(tok) if isinstance(tok, bytes) else 0)
    n_objs = header[0]
    first = header[1]
    pairs = []
    for _ in range(n_objs):
        o = int(sp.read_token())
        off = int(sp.read_token())
        pairs.append((o, off))
    for o, off in pairs:
        if o == index:
            op = Parser(raw, off)
            return op.parse_value()
    raise PDFError(f"object {index} not found in ObjStm {objstm_num}")


def load_doc(path):
    with open(path, "rb") as f:
        data = f.read()
    m = re.search(rb"startxref\s+(\d+)", data)
    if not m:
        raise PDFError(f"no startxref in {path}")
    startxref = int(m.group(1))
    if data[startxref:startxref + 4] == b"xref":
        entries, trailer = parse_classic_xref(data, startxref)
    else:
        entries, trailer = parse_xref_stream(data, startxref)
        prev = dict_get(trailer, b"/Prev")
        while isinstance(prev, int):
            more, trailer = parse_xref_stream(data, prev)
            entries.update(more)
            prev = dict_get(trailer, b"/Prev")
    root = dict_get(trailer, b"/Root")
    if not (isinstance(root, tuple) and root[0] == "ref"):
        raise PDFError(f"no /Root in trailer of {path}")
    if dict_get(trailer, b"/Encrypt") is not None:
        raise PDFError(f"encrypted PDF not supported: {path}")
    objects = {}
    for num, (kind, a, b) in entries.items():
        if kind == "off":
            try:
                objects[num] = Parser(data, a).parse_object(a)
            except Exception:
                continue
        elif kind == "objstm":
            try:
                val = parse_objstm(data, a, b)
                objects[num] = (num, 0, val, None, 0)
            except Exception:
                continue
    return data, entries, trailer, root[1], objects


def serialize_value(v, renum):
    if v is True:
        return b"true"
    if v is False:
        return b"false"
    if v is None:
        return b"null"
    if isinstance(v, int):
        return str(v).encode()
    if isinstance(v, bytes):
        return v
    if isinstance(v, tuple):
        if v[0] == "ref":
            n, g = v[1], v[2]
            return b"%d %d R" % (renum.get(n, n), g)
        if v[0] == "array":
            return b"[" + b" ".join(serialize_value(x, renum) for x in v[1]) + b"]"
        if v[0] == "dict":
            parts = []
            for k, val in v[1]:
                parts.append(k + b" " + serialize_value(val, renum))
            return b"<<" + b" ".join(parts) + b">>"
    raise PDFError(f"cannot serialize {v!r}")


def serialize_object(objnum, gen, value, stream, renum):
    head = b"%d %d obj\n" % (objnum, gen)
    body = serialize_value(value, renum)
    if stream is not None:
        return head + body + b"\nstream\n" + stream + b"\nendstream\nendobj\n"
    return head + body + b"\nendobj\n"


def pure_python_merge():
    doc1 = load_doc(INPUTS[0])
    doc2 = load_doc(INPUTS[1])
    objs1 = doc1[4]
    objs2 = doc2[4]
    if not objs1 or not objs2:
        raise PDFError("no parseable objects")
    max1 = max(objs1)
    max2 = max(objs2)
    offset2 = max1 + 1
    newroot_num = offset2 + max2

    cat1_num = doc1[3]
    cat2_num = doc2[3]
    cat1 = objs1.get(cat1_num)
    cat2 = objs2.get(cat2_num)
    if cat1 is None:
        raise PDFError("catalog 1 missing")
    pages1_ref = dict_get(cat1[2], b"/Pages")
    pages2_ref = dict_get(cat2[2], b"/Pages")
    if not (isinstance(pages1_ref, tuple) and pages1_ref[0] == "ref"):
        raise PDFError("no /Pages in catalog 1")
    if not (isinstance(pages2_ref, tuple) and pages2_ref[0] == "ref"):
        raise PDFError("no /Pages in catalog 2")
    pages1_num = pages1_ref[1]
    pages2_num = pages2_ref[1] + offset2

    count1 = 0
    count2 = 0

    def count_pages(pages_value):
        c = dict_get(pages_value, b"/Count")
        return c if isinstance(c, int) else 0

    p1 = objs1.get(pages1_ref[1])
    p2 = objs2.get(pages2_ref[1])
    if p1 is not None:
        count1 = count_pages(p1[2])
    if p2 is not None:
        count2 = count_pages(p2[2])

    newroot_value = ("dict", [
        (b"/Type", b"/Pages"),
        (b"/Kids", ("array", [
            ("ref", pages1_ref[1], 0),
            ("ref", pages2_num, 0),
        ])),
        (b"/Count", count1 + count2),
    ])

    if p1 is not None:
        dict_set(p1[2], b"/Parent", ("ref", newroot_num, 0))
    if p2 is not None:
        dict_set(p2[2], b"/Parent", ("ref", newroot_num, 0))

    dict_set(cat1[2], b"/Pages", ("ref", newroot_num, 0))

    renum = {n: n for n in objs1}
    renum.update({n: n + offset2 for n in objs2})

    out = bytearray()
    xref = []
    max_out = newroot_num

    def emit(num, gen, value, stream):
        nonlocal out
        off = len(out)
        out += serialize_object(num, gen, value, stream, renum)
        while len(xref) < num + 1:
            xref.append(None)
        xref[num] = (off, gen)

    for n in sorted(objs1):
        o = objs1[n]
        emit(n, o[1], o[2], o[3])
    for n in sorted(objs2):
        o = objs2[n]
        emit(n + offset2, o[1], o[2], o[3])
    emit(newroot_num, 0, newroot_value, None)

    header = b"%PDF-1.4\n"
    body = bytes(out)
    xref_offset = len(header) + len(body)
    size = max_out + 1
    lines = [b"xref\n", b"0 %d\n" % size, b"0000000000 65535 f \n"]
    for i in range(1, size):
        e = xref[i] if i < len(xref) else None
        if e is None:
            lines.append(b"0000000000 00000 f \n")
        else:
            lines.append(b"%010d %05d n \n" % (e[0], e[1]))
    trailer = b"trailer\n<< /Size %d /Root %d 0 R >>\n" % (size, cat1_num)
    tail = b"".join(lines) + trailer + b"startxref\n%d\n%%%%EOF\n" % xref_offset
    with open(OUTPUT, "wb") as f:
        f.write(header + body + tail)
    return f"pure-python (pages 1={count1}, 2={count2})"


def main():
    lib = merge_with_library()
    if lib:
        print("MERGED via", lib)
        return
    cli = merge_with_cli()
    if cli:
        print("MERGED via", cli)
        return
    method = pure_python_merge()
    if os.path.exists(OUTPUT) and os.path.getsize(OUTPUT) > 0:
        print("MERGED via", method)
        print("Output:", OUTPUT, os.path.getsize(OUTPUT), "bytes")
    else:
        sys.exit("merge produced no output")


if __name__ == "__main__":
    main()

"""Merge report_part1.pdf and report_part2.pdf into combined_report.pdf.

Strategy 1: any available PDF CLI tool.
Strategy 2: pure-Python merge using only the standard library.
"""
import os
import re
import shutil
import subprocess
import sys
import zlib

INPUTS = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT = "combined_report.pdf"

for name in INPUTS:
    if not os.path.exists(name):
        sys.exit(f"Missing input file: {name}")

WHITESPACE = b"\x00\t\n\x0c\r "
DELIMS = b"()<>[]{}/%"


# --------------------------------------------------------------------------
# Strategy 1: CLI tools
# --------------------------------------------------------------------------
def merge_with_cli():
    clis = [
        (["qpdf", "--empty", "--pages"] + INPUTS + ["--", OUTPUT], "qpdf"),
        (["pdfunite"] + INPUTS + [OUTPUT], "pdfunite"),
        (["pdftk"] + INPUTS + ["cat", "output", OUTPUT], "pdftk"),
        (["gs", "-q", "-dNOPAUSE", "-dBATCH", "-sDEVICE=pdfwrite",
          "-sOutputFile=" + OUTPUT] + INPUTS, "ghostscript"),
        (["mutool", "merge", "-o", OUTPUT] + INPUTS, "mutool"),
        (["cpdf", "-merge"] + INPUTS + ["-o", OUTPUT], "cpdf"),
        (["pdfjam"] + INPUTS + ["--outfile", OUTPUT], "pdfjam"),
        (["stapler", "cat"] + INPUTS + ["-o", OUTPUT], "stapler"),
    ]
    for cmd, name in clis:
        if shutil.which(cmd[0]):
            try:
                subprocess.run(cmd, check=True, timeout=30)
                if os.path.exists(OUTPUT) and os.path.getsize(OUTPUT) > 0:
                    return name
            except Exception:
                continue
    return None


# --------------------------------------------------------------------------
# Strategy 2: pure-Python merge (stdlib only)
# --------------------------------------------------------------------------
class PDFError(Exception):
    pass


class Parser:
    def __init__(self, data, pos=0):
        self.data = data
        self.pos = pos
        self.n = len(data)

    def skip_ws(self):
        d = self.data
        while self.pos < self.n and d[self.pos] in WHITESPACE:
            self.pos += 1

    def read_token(self):
        self.skip_ws()
        d = self.data
        if self.pos >= self.n:
            raise PDFError("unexpected EOF in token")
        c = d[self.pos]
        if c in b"+-.0123456789":
            start = self.pos
            while self.pos < self.n and d[self.pos] in b"+-.0123456789":
                self.pos += 1
            return d[start:self.pos]
        if c == 47:  # /
            start = self.pos
            self.pos += 1
            while self.pos < self.n and d[self.pos] not in WHITESPACE + DELIMS:
                self.pos += 1
            return d[start:self.pos]
        if c == 40:  # (
            start = self.pos
            depth = 1
            self.pos += 1
            while self.pos < self.n:
                ch = d[self.pos]
                if ch == 92:
                    self.pos += 2
                    continue
                if ch == 40:
                    depth += 1
                elif ch == 41:
                    depth -= 1
                    if depth == 0:
                        self.pos += 1
                        break
                self.pos += 1
            return d[start:self.pos]
        if c == 60:
            if d[self.pos + 1:self.pos + 2] == b"<":
                self.pos += 2
                items = []
                while True:
                    self.skip_ws()
                    if self.data[self.pos:self.pos + 2] == b">>":
                        self.pos += 2
                        break
                    key = self.read_token()
                    if self.data[self.pos:self.pos + 2] == b">>":
                        self.pos += 2
                        break
                    items.append((key, self.parse_value()))
                return ("dict", items)
            start = self.pos
            self.pos += 1
            while self.pos < self.n and d[self.pos] != 62:
                self.pos += 1
            if self.pos < self.n:
                self.pos += 1
            return d[start:self.pos]
        if c == 91:  # [
            self.pos += 1
            arr = []
            while True:
                self.skip_ws()
                if self.pos >= self.n:
                    raise PDFError("EOF inside array")
                if d[self.pos] == 93:
                    self.pos += 1
                    break
                arr.append(self.parse_value())
            return ("array", arr)
        if c == 93:
            self.pos += 1
            return b"]"
        start = self.pos
        while self.pos < self.n and d[self.pos] not in WHITESPACE + DELIMS:
            self.pos += 1
        tok = d[start:self.pos]
        if tok == b"true":
            return True
        if tok == b"false":
            return False
        if tok == b"null":
            return None
        return tok

    def parse_value(self):
        self.skip_ws()
        d = self.data
        if d[self.pos:self.pos + 2] == b"<<":
            return self.read_token()
        c = d[self.pos]
        if c in (40, 60, 91):
            return self.read_token()
        tok = self.read_token()
        if tok is True or tok is False or tok is None:
            return tok
        if isinstance(tok, bytes) and re.fullmatch(rb"[+-]?\d+", tok):
            num = int(tok)
            save = self.pos
            t2 = self.read_token()
            if isinstance(t2, bytes) and re.fullmatch(rb"\d+", t2):
                save2 = self.pos
                t3 = self.read_token()
                if t3 == b"R":
                    return ("ref", num, int(t2))
                self.pos = save2
            self.pos = save
            return num
        return tok

    def parse_object(self, offset):
        self.pos = offset
        self.skip_ws()
        ntok = self.read_token()
        if not isinstance(ntok, bytes) or not re.fullmatch(rb"\d+", ntok):
            raise PDFError(f"bad object header at {offset}")
        num = int(ntok)
        gtok = self.read_token()
        gen = int(gtok) if isinstance(gtok, bytes) else 0
        k = self.read_token()
        if k != b"obj":
            raise PDFError(f"'obj' expected at {offset}")
        value = self.parse_value()
        self.skip_ws()
        if self.data[self.pos:self.pos + 6] == b"stream":
            eol = self.pos + 6
            if self.data[eol:eol + 2] == b"\r\n":
                eol += 2
            elif self.data[eol:eol + 1] in (b"\n", b"\r"):
                eol += 1
            start = eol
            end = self.data.find(b"endstream", start)
            if end < 0:
                raise PDFError(f"no endstream in object {num}")
            stream = self.data[start:end]
            self.pos = end + len(b"endstream")
            self.skip_ws()
            eo = self.data.find(b"endobj", self.pos)
            if eo < 0:
                raise PDFError(f"no endobj after stream in object {num}")
            return num, gen, value, stream, eo + 6
        eo = self.data.find(b"endobj", self.pos)
        if eo < 0:
            raise PDFError(f"no endobj in object {num}")
        return num, gen, value, None, eo + 6


def dict_get(d, key):
    if isinstance(d, tuple) and d[0] == "dict":
        for k, v in d[1]:
            if k == key:
                return v
    return None


def dict_set(d, key, val):
    items = d[1]
    for i, (k, _) in enumerate(items):
        if k == key:
            items[i] = (key, val)
            return
    items.append((key, val))


def parse_classic_xref(data, startxref):
    entries = {}
    trailer = None
    pos = startxref
    while pos is not None:
        if data[pos:pos + 4] != b"xref":
            raise PDFError(f"bad xref at {pos}")
        pos += 4
        while True:
            while pos < len(data) and data[pos] in WHITESPACE:
                pos += 1
            if pos >= len(data):
                break
            if data[pos:pos + 7] == b"trailer":
                p = Parser(data, pos + 7)
                trailer = p.parse_value()
                prev = dict_get(trailer, b"/Prev")
                pos = prev if isinstance(prev, int) else None
                xrefstm = dict_get(trailer, b"/XRefStm")
                if isinstance(xrefstm, int):
                    try:
                        stm_entries, _ = parse_xref_stream(data, xrefstm)
                        entries.update(stm_entries)
                    except Exception:
                        pass
                break
            m = re.match(rb"(\d+)\s+(\d+)", data[pos:])
            if not m:
                raise PDFError("bad xref subsection")
            start = int(m.group(1))
            count = int(m.group(2))
            pos += m.end()
            for _ in range(count):
                ent = data[pos:pos + 20]
                off = int(ent[0:10])
                gen = int(ent[11:16])
                typ = ent[17:18]
                pos += 20
                if typ == b"n":
                    entries[start] = ("off", off, gen)
                elif typ == b"f":
                    entries[start] = ("free", off, gen)
                start += 1
    return entries, trailer


def parse_xref_stream(data, startxref):
    p = Parser(data, startxref)
    num, gen, value, stream, _ = p.parse_object(startxref)
    W = dict_get(value, b"/W")
    if not (isinstance(W, tuple) and W[0] == "array"):
        raise PDFError("xref stream without /W")
    widths = [w for w in W[1] if isinstance(w, int)]
    Index = dict_get(value, b"/Index")
    if isinstance(Index, tuple) and Index[0] == "array":
        pairs = [v for v in Index[1] if isinstance(v, int)]
    else:
        size = dict_get(value, b"/Size")
        pairs = [0, size if isinstance(size, int) else 0]
    try:
        raw = zlib.decompress(stream)
    except Exception:
        raw = stream
    entries = {}
    field_bytes = b"".join(widths)
    pos = 0
    for i in range(0, len(pairs), 2):
        start = pairs[i]
        count = pairs[i + 1]
        for _ in range(count):
            chunk = raw[pos:pos + field_bytes]
            pos += field_bytes
            fields = []
            off = 0
            for w in widths:
                fields.append(int.from_bytes(chunk[off:off + w], "big"))
                off += w
            typ = fields[0] if widths and widths[0] > 0 else 1
            if typ == 1:
                entries[start] = ("off", fields[1], fields[2])
            elif typ == 2:
                entries[start] = ("objstm", fields[1], fields[2])
            else:
                entries[start] = ("free", fields[1], fields[2])
            start += 1
    return entries, value


def parse_objstm(data, objstm_num, index):
    p = Parser(data, objstm_num)
    num, gen, value, stream, _ = p.parse_object(objstm_num)
    raw = zlib.decompress(stream) if stream else b""
    sp = Parser(raw, 0)
    header = []
    for _ in range(2):
        tok = sp.read_token()
        header.append(int(tok) if isinstance(tok, bytes) else 0)
    n_objs = header[0]
    first = header[1]
    pairs = []
    for _ in range(n_objs):
        o = int(sp.read_token())
        off = int(sp.read_token())
        pairs.append((o, off))
    for o, off in pairs:
        if o == index:
            op = Parser(raw, off)
            return op.parse_value()
    raise PDFError(f"object {index} not found in ObjStm {objstm_num}")


def load_doc(path):
    with open(path, "rb") as f:
        data = f.read()
    m = re.search(rb"startxref\s+(\d+)", data)
    if not m:
        raise PDFError(f"no startxref in {path}")
    startxref = int(m.group(1))
    if data[startxref:startxref + 4] == b"xref":
        entries, trailer = parse_classic_xref(data, startxref)
    else:
        entries, trailer = parse_xref_stream(data, startxref)
        prev = dict_get(trailer, b"/Prev")
        while isinstance(prev, int):
            more, trailer = parse_xref_stream(data, prev)
            entries.update(more)
            prev = dict_get(trailer, b"/Prev")
    root = dict_get(trailer, b"/Root")
    if not (isinstance(root, tuple) and root[0] == "ref"):
        raise PDFError(f"no /Root in trailer of {path}")
    if dict_get(trailer, b"/Encrypt") is not None:
        raise PDFError(f"encrypted PDF not supported: {path}")
    objects = {}
    for num, (kind, a, b) in entries.items():
        if kind == "off":
            try:
                objects[num] = Parser(data, a).parse_object(a)
            except Exception:
                continue
        elif kind == "objstm":
            try:
                val = parse_objstm(data, a, b)
                objects[num] = (num, 0, val, None, 0)
            except Exception:
                continue
    return data, entries, trailer, root[1], objects


def serialize_value(v, renum):
    if v is True:
        return b"true"
    if v is False:
        return b"false"
    if v is None:
        return b"null"
    if isinstance(v, int):
        return str(v).encode()
    if isinstance(v, bytes):
        return v
    if isinstance(v, tuple):
        if v[0] == "ref":
            n, g = v[1], v[2]
            return b"%d %d R" % (renum.get(n, n), g)
        if v[0] == "array":
            return b"[" + b" ".join(serialize_value(x, renum) for x in v[1]) + b"]"
        if v[0] == "dict":
            parts = []
            for k, val in v[1]:
                parts.append(k + b" " + serialize_value(val, renum))
            return b"<<" + b" ".join(parts) + b">>"
    raise PDFError(f"cannot serialize {v!r}")


def serialize_object(objnum, gen, value, stream, renum):
    head = b"%d %d obj\n" % (objnum, gen)
    body = serialize_value(value, renum)
    if stream is not None:
        return head + body + b"\nstream\n" + stream + b"\nendstream\nendobj\n"
    return head + body + b"\nendobj\n"


def pure_python_merge():
    doc1 = load_doc(INPUTS[0])
    doc2 = load_doc(INPUTS[1])
    objs1 = doc1[4]
    objs2 = doc2[4]
    if not objs1 or not objs2:
        raise PDFError("no parseable objects")
    max1 = max(objs1)
    max2 = max(objs2)
    offset2 = max1 + 1
    newroot_num = offset2 + max2

    cat1_num = doc1[3]
    cat2_num = doc2[3]
    cat1 = objs1.get(cat1_num)
    cat2 = objs2.get(cat2_num)
    if cat1 is None:
        raise PDFError("catalog 1 missing")
    pages1_ref = dict_get(cat1[2], b"/Pages")
    pages2_ref = dict_get(cat2[2], b"/Pages")
    if not (isinstance(pages1_ref, tuple) and pages1_ref[0] == "ref"):
        raise PDFError("no /Pages in catalog 1")
    if not (isinstance(pages2_ref, tuple) and pages2_ref[0] == "ref"):
        raise PDFError("no /Pages in catalog 2")
    pages1_num = pages1_ref[1]
    pages2_num = pages2_ref[1] + offset2

    count1 = 0
    count2 = 0

    def count_pages(pages_value):
        c = dict_get(pages_value, b"/Count")
        return c if isinstance(c, int) else 0

    p1 = objs1.get(pages1_ref[1])
    p2 = objs2.get(pages2_ref[1])
    if p1 is not None:
        count1 = count_pages(p1[2])
    if p2 is not None:
        count2 = count_pages(p2[2])

    newroot_value = ("dict", [
        (b"/Type", b"/Pages"),
        (b"/Kids", ("array", [
            ("ref", pages1_ref[1], 0),
            ("ref", pages2_num, 0),
        ])),
        (b"/Count", count1 + count2),
    ])

    if p1 is not None:
        dict_set(p1[2], b"/Parent", ("ref", newroot_num, 0))
    if p2 is not None:
        dict_set(p2[2], b"/Parent", ("ref", newroot_num, 0))

    dict_set(cat1[2], b"/Pages", ("ref", newroot_num, 0))

    renum = {n: n for n in objs1}
    renum.update({n: n + offset2 for n in objs2})

    out = bytearray()
    xref = []
    max_out = newroot_num

    def emit(num, gen, value, stream):
        nonlocal out
        off = len(out)
        out += serialize_object(num, gen, value, stream, renum)
        while len(xref) < num + 1:
            xref.append(None)
        xref[num] = (off, gen)

    for n in sorted(objs1):
        o = objs1[n]
        emit(n, o[1], o[2], o[3])
    for n in sorted(objs2):
        o = objs2[n]
        emit(n + offset2, o[1], o[2], o[3])
    emit(newroot_num, 0, newroot_value, None)

    header = b"%PDF-1.4\n"
    body = bytes(out)
    xref_offset = len(header) + len(body)
    size = max_out + 1
    lines = [b"xref\n", b"0 %d\n" % size, b"0000000000 65535 f \n"]
    for i in range(1, size):
        e = xref[i] if i < len(xref) else None
        if e is None:
            lines.append(b"0000000000 00000 f \n")
        else:
            lines.append(b"%010d %05d n \n" % (e[0], e[1]))
    trailer = b"trailer\n<< /Size %d /Root %d 0 R >>\n" % (size, cat1_num)
    tail = b"".join(lines) + trailer + b"startxref\n%d\n%%%%EOF\n" % xref_offset
    with open(OUTPUT, "wb") as f:
        f.write(header + body + tail)
    return f"pure-python (pages 1={count1}, 2={count2})"


def validate():
    with open(OUTPUT, "rb") as f:
        data = f.read()
    if not data.startswith(b"%PDF"):
        raise PDFError("output does not start with %PDF")
    m = re.search(rb"startxref\s+(\d+)\s*%%EOF\s*$", data)
    if not m:
        raise PDFError("output missing valid startxref/EOF")
    off = int(m.group(1))
    if data[off:off + 4] != b"xref":
        raise PDFError("startxref does not point at xref")
    # every xref 'n' entry must point at an object header
    entries = 0
    for num, (kind, a, b) in parse_classic_xref(data, off)[0].items():
        if kind == "off":
            entries += 1
            try:
                Parser(data, a).parse_object(a)
            except Exception as exc:
                raise PDFError(f"bad entry obj {num}: {exc}")
    return entries


def main():
    cli = merge_with_cli()
    if cli:
        print("MERGED via", cli)
    else:
        method = pure_python_merge()
        print("MERGED via", method)
    n_objs = validate()
    print("Output:", OUTPUT, os.path.getsize(OUTPUT), "bytes,",
          n_objs, "objects, validation OK")


if __name__ == "__main__":
    main()

