"""Merge report_part1.pdf and report_part2.pdf into combined_report.pdf.

Strategy 1: use any available PDF library found on sys.path candidates.
Strategy 2: use any available PDF CLI tool.
Strategy 3: pure-Python merge using only the standard library.
"""
import importlib
import os
import re
import shutil
import subprocess
import sys
import zlib

INPUTS = ["report_part1.pdf", "report_part2.pdf"]
OUTPUT = "combined_report.pdf"

for name in INPUTS:
    if not os.path.exists(name):
        sys.exit(f"Missing input file: {name}")

WHITESPACE = b"\x00\t\n\x0c\r "
DELIMS = b"()<>[]{}/%"


# --------------------------------------------------------------------------
# Strategy 1: library discovery via sys.path candidates
# --------------------------------------------------------------------------
def find_site_packages():
    found = []
    roots = [
        os.getcwd(),
        os.path.abspath(os.path.join(os.getcwd(), "..")),
        os.path.abspath(os.path.join(os.getcwd(), "../..")),
        ".codex",
        ".tools",
        "/usr/lib",
        "/usr/local/lib",
    ]
    for root in roots:
        if not root or not os.path.isdir(root):
            continue
        for dirpath, dirnames, filenames in os.walk(root):
            depth = dirpath[len(root):].count(os.sep)
            if depth > 5:
                dirnames[:] = []
                continue
            base = os.path.basename(dirpath)
            if base in ("site-packages", "dist-packages"):
                found.append(dirpath)
                dirnames[:] = []
    return found


def merge_with_library():
    for sp in find_site_packages():
        if sp not in sys.path:
            sys.path.insert(0, sp)
    modules = ["pypdf", "PyPDF2", "pypdfium2", "fitz", "pikepdf", "pdfrw"]
    available = [m for m in modules if importlib.util.find_spec(m)]
    if "pypdf" in available:
        from pypdf import PdfReader, PdfWriter
        w = PdfWriter()
        for n in INPUTS:
            for p in PdfReader(n).pages:
                w.add_page(p)
        with open(OUTPUT, "wb") as f:
            w.write(f)
        return "pypdf"
    if "PyPDF2" in available:
        from PyPDF2 import PdfReader, PdfWriter
        w = PdfWriter()
        for n in INPUTS:
            for p in PdfReader(n).pages:
                w.add_page(p)
        with open(OUTPUT, "wb") as f:
            w.write(f)
        return "PyPDF2"
    if "pypdfium2" in available:
        import pypdfium2 as pdfium
        out = pdfium.PdfDocument.new()
        for n in INPUTS:
            src = pdfium.PdfDocument(n)
            out.import_pages(src)
            src.close()
        out.save(OUTPUT)
        out.close()
        return "pypdfium2"
    if "fitz" in available:
        import fitz
        out = fitz.open()
        for n in INPUTS:
            src = fitz.open(n)
            out.insert_pdf(src)
            src.close()
        out.save(OUTPUT)
        out.close()
        return "fitz"
    if "pikepdf" in available:
        import pikepdf
        out = pikepdf.new()
        for n in INPUTS:
            with pikepdf.open(n) as src:
                out.pages.extend(src.pages)
        out.save(OUTPUT)
        return "pikepdf"
    if "pdfrw" in available:
        from pdfrw import PdfReader, PdfWriter
        out = PdfWriter()
        for n in INPUTS:
            out.addpages(PdfReader(n).pages)
        out.write(OUTPUT)
        return "pdfrw"
    return None


