# --------------------------------------------------------------------------
def merge_with_cli():
    clis = [
        (["qpdf", "--empty", "--pages"] + INPUTS + ["--", OUTPUT], "qpdf"),
        (["pdfunite"] + INPUTS + [OUTPUT], "pdfunite"),
        (["pdftk"] + INPUTS + ["cat", "output", OUTPUT], "pdftk"),
        (["gs", "-q", "-dNOPAUSE", "-dBATCH", "-sDEVICE=pdfwrite",
          "-sOutputFile=" + OUTPUT] + INPUTS, "ghostscript"),
        (["mutool", "merge", "-o", OUTPUT] + INPUTS, "mutool"),
        (["cpdf", "-merge"] + INPUTS + ["-o", OUTPUT], "cpdf"),
        (["pdfjam"] + INPUTS + ["--outfile", OUTPUT], "pdfjam"),
        (["stapler", "cat"] + INPUTS + ["-o", OUTPUT], "stapler"),
    ]
    for cmd, name in clis:
        if shutil.which(cmd[0]):
            try:
                subprocess.run(cmd, check=True)
                if os.path.exists(OUTPUT) and os.path.getsize(OUTPUT) > 0:
                    return name
            except Exception:
                continue
    return None


