    else:
        size = dict_get(value, b"/Size")
        pairs = [0, size if isinstance(size, int) else 0]
    try:
        raw = zlib.decompress(stream)
    except Exception:
        raw = stream
    entries = {}
    field_bytes = b"".join(widths)
    pos = 0
    for i in range(0, len(pairs), 2):
        start = pairs[i]
        count = pairs[i + 1]
        for _ in range(count):
            chunk = raw[pos:pos + field_bytes]
            pos += field_bytes
            fields = []
            off = 0
            for w in widths:
                fields.append(int.from_bytes(chunk[off:off + w], "big"))
                off += w
            typ = fields[0] if widths and widths[0] > 0 else 1
            if typ == 1:
                entries[start] = ("off", fields[1], fields[2])
            elif typ == 2:
                entries[start] = ("objstm", fields[1], fields[2])
            else:
                entries[start] = ("free", fields[1], fields[2])
            start += 1
    return entries, value


def parse_objstm(data, objstm_num, index):
    p = Parser(data, objstm_num)
    num, gen, value, stream, _ = p.parse_object(objstm_num)
    raw = zlib.decompress(stream) if stream else b""
    sp = Parser(raw, 0)
    header = []
    for _ in range(2):
        tok = sp.read_token()
        header.append(int(tok) if isinstance(tok, bytes) else 0)
    n_objs = header[0]
    first = header[1]
    pairs = []
    for _ in range(n_objs):
        o = int(sp.read_token())
        off = int(sp.read_token())
        pairs.append((o, off))
    for o, off in pairs:
        if o == index:
            op = Parser(raw, off)
            return op.parse_value()
    raise PDFError(f"object {index} not found in ObjStm {objstm_num}")


def load_doc(path):
    with open(path, "rb") as f:
        data = f.read()
    log(f"  loaded {path}: {len(data)} bytes, header={data[:16]!r}")
    m = re.search(rb"startxref\s+(\d+)", data)
    if not m:
        raise PDFError(f"no startxref in {path}")
    startxref = int(m.group(1))
    log(f"  startxref={startxref}, at={data[startxref:startxref+16]!r}")
    if data[startxref:startxref + 4] == b"xref":
        entries, trailer = parse_classic_xref(data, startxref)
        log(f"  classic xref: {len(entries)} entries")
    else:
        entries, trailer = parse_xref_stream(data, startxref)
        prev = dict_get(trailer, b"/Prev")
        while isinstance(prev, int):
            more, trailer = parse_xref_stream(data, prev)
            entries.update(more)
            prev = dict_get(trailer, b"/Prev")
        log(f"  xref stream: {len(entries)} entries")
    root = dict_get(trailer, b"/Root")
    if not (isinstance(root, tuple) and root[0] == "ref"):
        raise PDFError(f"no /Root in trailer of {path}")
    if dict_get(trailer, b"/Encrypt") is not None:
        raise PDFError(f"encrypted PDF not supported: {path}")
    objects = {}
    for num, (kind, a, b) in entries.items():
        if kind == "off":
            try:
                objects[num] = Parser(data, a).parse_object(a)
            except Exception:
                continue
        elif kind == "objstm":
            try:
                val = parse_objstm(data, a, b)
                objects[num] = (num, 0, val, None, 0)
            except Exception:
                continue
    log(f"  parsed {len(objects)} objects")
    return data, entries, trailer, root[1], objects


def serialize_value(v, renum):
    if v is True:
        return b"true"
    if v is False:
        return b"false"
    if v is None:
        return b"null"
    if isinstance(v, int):
        return str(v).encode()
    if isinstance(v, bytes):
        return v
    if isinstance(v, tuple):
        if v[0] == "ref":
            n, g = v[1], v[2]
            return b"%d %d R" % (renum.get(n, n), g)
        if v[0] == "array":
            return b"[" + b" ".join(serialize_value(x, renum) for x in v[1]) + b"]"
        if v[0] == "dict":
            parts = []
            for k, val in v[1]:
                parts.append(k + b" " + serialize_value(val, renum))
            return b"<<" + b" ".join(parts) + b">>"
    raise PDFError(f"cannot serialize {v!r}")


def serialize_object(objnum, gen, value, stream, renum):
    head = b"%d %d obj\n" % (objnum, gen)
    body = serialize_value(value, renum)
    if stream is not None:
        return head + body + b"\nstream\n" + stream + b"\nendstream\nendobj\n"
    return head + body + b"\nendobj\n"


def pure_python_merge():
    log("parsing doc1...")
    doc1 = load_doc(INPUTS[0])
    log("parsing doc2...")
    doc2 = load_doc(INPUTS[1])
    objs1 = doc1[4]
    objs2 = doc2[4]
    if not objs1 or not objs2:
        raise PDFError("no parseable objects")
    max1 = max(objs1)
    max2 = max(objs2)
    offset2 = max1 + 1
    newroot_num = offset2 + max2

    cat1_num = doc1[3]
    cat2_num = doc2[3]
    cat1 = objs1.get(cat1_num)
    cat2 = objs2.get(cat2_num)
    if cat1 is None:
        raise PDFError("catalog 1 missing")
    pages1_ref = dict_get(cat1[2], b"/Pages")
    pages2_ref = dict_get(cat2[2], b"/Pages")
    if not (isinstance(pages1_ref, tuple) and pages1_ref[0] == "ref"):
        raise PDFError("no /Pages in catalog 1")
    if not (isinstance(pages2_ref, tuple) and pages2_ref[0] == "ref"):
        raise PDFError("no /Pages in catalog 2")
    pages1_num = pages1_ref[1]
    pages2_num = pages2_ref[1] + offset2

    count1 = 0
    count2 = 0

    def count_pages(pages_value):
        c = dict_get(pages_value, b"/Count")
        return c if isinstance(c, int) else 0

    p1 = objs1.get(pages1_ref[1])
    p2 = objs2.get(pages2_ref[1])
    if p1 is not None:
        count1 = count_pages(p1[2])
    if p2 is not None:
        count2 = count_pages(p2[2])

    newroot_value = ("dict", [
        (b"/Type", b"/Pages"),
        (b"/Kids", ("array", [
            ("ref", pages1_ref[1], 0),
            ("ref", pages2_num, 0),
        ])),
        (b"/Count", count1 + count2),
    ])

    if p1 is not None:
        dict_set(p1[2], b"/Parent", ("ref", newroot_num, 0))
    if p2 is not None:
        dict_set(p2[2], b"/Parent", ("ref", newroot_num, 0))

    dict_set(cat1[2], b"/Pages", ("ref", newroot_num, 0))

    renum = {n: n for n in objs1}
    renum.update({n: n + offset2 for n in objs2})

    out = bytearray()
    xref = []
    max_out = newroot_num

    def emit(num, gen, value, stream):
        nonlocal out
        off = len(out)
        out += serialize_object(num, gen, value, stream, renum)
        while len(xref) < num + 1:
            xref.append(None)
        xref[num] = (off, gen)

    log("serializing objects...")
    for n in sorted(objs1):
        o = objs1[n]
        emit(n, o[1], o[2], o[3])
    for n in sorted(objs2):
        o = objs2[n]
        emit(n + offset2, o[1], o[2], o[3])
    emit(newroot_num, 0, newroot_value, None)

    header = b"%PDF-1.4\n"
    body = bytes(out)
    xref_offset = len(header) + len(body)
    size = max_out + 1
    lines = [b"xref\n", b"0 %d\n" % size, b"0000000000 65535 f \n"]
    for i in range(1, size):
        e = xref[i] if i < len(xref) else None
        if e is None:
            lines.append(b"0000000000 00000 f \n")
        else:
            lines.append(b"%010d %05d n \n" % (e[0], e[1]))
    trailer = b"trailer\n<< /Size %d /Root %d 0 R >>\n" % (size, cat1_num)
    tail = b"".join(lines) + trailer + b"startxref\n%d\n%%%%EOF\n" % xref_offset
    with open(OUTPUT, "wb") as f:
        f.write(header + body + tail)
    log("wrote", OUTPUT)
    return f"pure-python (pages 1={count1}, 2={count2})"


def validate():
    with open(OUTPUT, "rb") as f:
        data = f.read()
    if not data.startswith(b"%PDF"):
        raise PDFError("output does not start with %PDF")
    m = re.search(rb"startxref\s+(\d+)\s*%%EOF\s*$", data)
    if not m:
        raise PDFError("output missing valid startxref/EOF")
    off = int(m.group(1))
    if data[off:off + 4] != b"xref":
        raise PDFError("startxref does not point at xref")
    entries = 0
    for num, (kind, a, b) in parse_classic_xref(data, off)[0].items():
        if kind == "off":
            entries += 1
            try:
                Parser(data, a).parse_object(a)
            except Exception as exc:
                raise PDFError(f"bad entry obj {num}: {exc}")
    return entries


def main():
    log("checking CLI tools...")
    cli = merge_with_cli()
    if cli:
        log("MERGED via " + cli)
    else:
        log("no CLI tool; using pure-python merge")
        method = pure_python_merge()
        log("MERGED via " + method)
    n_objs = validate()
    log("validation OK: %d objects, %d bytes" % (n_objs, os.path.getsize(OUTPUT)))


if __name__ == "__main__":
    main()
